    difficulty, servings, rating, tips, nutrition
) VALUES 
(
    '11111111-1111-1111-1111-111111111103',
    'Crispy South Indian Masala Dosa',
    'Golden fermented rice and lentil crepe stuffed with aromatic spiced potato masala, served with coconut chutney and tangy sambar.',
    'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?w=800&auto=format&fit=crop&q=80',
    'South Indian',
    'Breakfast',
    'VEGETARIAN',
    '[{"name":"Dosa Batter (Rice & Urad Dal)","quantity":"3 cups (fermented)","isOptional":false},{"name":"Potatoes (Aloo)","quantity":"4 medium (boiled & mashed)","isOptional":false},{"name":"Onions","quantity":"2 medium (thinly sliced)","isOptional":false},{"name":"Mustard Seeds & Curry Leaves","quantity":"1 tsp seeds, 10 leaves","isOptional":false},{"name":"Turmeric Powder & Green Chilies","quantity":"1/2 tsp turmeric, 3 chilies slit","isOptional":false},{"name":"Ghee / Cooking Oil","quantity":"3 tbsp","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Heat 1 tbsp oil in a pan. Sputter mustard seeds, chana dal, green chilies, and curry leaves."},{"step":2,"text":"Add sliced onions and sauté until translucent. Add turmeric and salt."},{"step":3,"text":"Add roughly mashed boiled potatoes and 1/4 cup water. Simmer on low heat for 3-4 minutes to create the filling."},{"step":4,"text":"Heat a flat cast iron tawa. Pour a ladle of fermented dosa batter in the center and spread outward in circular motions."},{"step":5,"text":"Drizzle ghee around the edges and cook on medium heat until the base turns golden and crisp."},{"step":6,"text":"Place potato masala in the center, fold over, and serve hot with coconut chutney and sambar."}]'::jsonb,
    '20 mins',
    '15 mins',
    '35 mins',
    'Medium',
    4,
    4.9,
    ARRAY['Ensure the tawa is medium-hot before spreading batter; sprinkle water and wipe with cloth to regulate temperature.', 'Mash potatoes coarsely, not into a paste, for authentic texture.'],
    '{"calories":320,"protein":"6g","carbs":"52g","fat":"10g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111104',
    'Amritsari Stuffed Aloo Paratha',
    'Crispy whole wheat flatbread generously stuffed with spiced mashed potatoes, fresh green chilies, and coriander, served with white butter.',
    'https://images.unsplash.com/photo-1626074353765-517a681e40be?w=800&auto=format&fit=crop&q=80',
    'North Indian',
    'Breakfast',
    'VEGETARIAN',
    '[{"name":"Whole Wheat Flour (Atta)","quantity":"2 cups","isOptional":false},{"name":"Potatoes (Aloo)","quantity":"3 large (boiled, peeled & grated)","isOptional":false},{"name":"Green Chilies & Fresh Ginger","quantity":"2 chilies chopped, 1 tsp grated ginger","isOptional":false},{"name":"Ajwain (Carom Seeds)","quantity":"1/2 tsp","isOptional":false},{"name":"Amchur (Dry Mango Powder) & Garam Masala","quantity":"1 tsp each","isOptional":false},{"name":"Desi Ghee or White Butter","quantity":"3 tbsp","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Knead wheat flour with water and a pinch of salt into a soft, pliable dough. Rest covered for 15 minutes."},{"step":2,"text":"In a bowl, mix grated boiled potatoes, green chilies, ginger, ajwain, amchur, garam masala, and fresh coriander."},{"step":3,"text":"Roll a ball of dough into a 4-inch disc. Place a generous ball of spiced potato filling in the center and seal edges tightly."},{"step":4,"text":"Gently roll the stuffed ball into an even, 7-8 inch paratha with light pressure to prevent tearing."},{"step":5,"text":"Roast on a hot tawa with ghee until crisp and spotted with golden brown on both sides."},{"step":6,"text":"Serve piping hot topped with a dollop of butter, cold curd, and spicy mango pickle."}]'::jsonb,
    '15 mins',
    '15 mins',
    '30 mins',
    'Easy',
    3,
    4.8,
    ARRAY['Cool boiled potatoes completely before mashing to ensure the filling stays dry and doesn''t tear the dough.', 'Use generous ghee for authentic dhabha-style crispiness.'],
    '{"calories":340,"protein":"8g","carbs":"58g","fat":"9g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111105',
    'Steamed Fluffy Idli with Vegetable Sambar',
    'Pillowy soft fermented rice cakes paired with a hearty, tangy lentil stew simmered with drumsticks, tomatoes, and South Indian spices.',
    'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=800&auto=format&fit=crop&q=80',
    'South Indian',
    'Breakfast',
    'VEGETARIAN',
    '[{"name":"Idli Batter (Fermented Rice & Urad Dal)","quantity":"3 cups","isOptional":false},{"name":"Toor Dal (Pigeon Peas)","quantity":"1 cup","isOptional":false},{"name":"Drumstick & Shallots (Sambar Onions)","quantity":"1 drumstick cut, 10 shallots","isOptional":false},{"name":"Ripe Tomatoes","quantity":"2 medium (diced)","isOptional":false},{"name":"Sambar Powder","quantity":"2 tbsp","isOptional":false},{"name":"Tamarind Paste","quantity":"1 tbsp dissolved in 1/2 cup warm water","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Grease idli plates with sesame oil. Pour fermented batter into the moulds and steam for 10-12 minutes until cooked."},{"step":2,"text":"Pressure cook toor dal with turmeric and 3 cups water until mushy (about 4 whistles). Whisk smooth."},{"step":3,"text":"Boil drumsticks, shallots, and diced tomatoes with tamarind water, sambar powder, and salt until vegetables are tender."},{"step":4,"text":"Add cooked toor dal to the vegetable pot and simmer for 5 minutes."},{"step":5,"text":"Temper mustard seeds, fenugreek seeds, curry leaves, and asafoetida in ghee and pour over sambar."},{"step":6,"text":"Unmould warm idlis using a wet spoon and serve swimming in aromatic hot sambar."}]'::jsonb,
    '15 mins',
    '20 mins',
    '35 mins',
    'Easy',
    4,
    4.8,
    ARRAY['Ferment the batter in a warm corner for 10-12 hours until it rises and becomes frothy for the softest idlis.', 'Use small shallots (sambar onions) for authentic South Indian flavor.'],
    '{"calories":250,"protein":"9g","carbs":"48g","fat":"2g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111106',
    'Mexican Black Bean & Tomato Breakfast Tacos',
    'Warm corn tortillas filled with cumin-spiced black beans, charred corn, fresh pico de gallo, avocado slices, and lime crema.',
    'https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?w=800&auto=format&fit=crop&q=80',
    'Mexican',
    'Breakfast',
    'VEGETARIAN',
    '[{"name":"Corn Tortillas","quantity":"6 small","isOptional":false},{"name":"Black Beans","quantity":"1 can (400g, rinsed and drained)","isOptional":false},{"name":"Ripe Tomatoes (Pico de Gallo)","quantity":"2 medium (finely diced)","isOptional":false},{"name":"Red Onion & Jalapeño","quantity":"1/2 onion diced, 1 jalapeño seeded","isOptional":false},{"name":"Fresh Cilantro & Lime","quantity":"1/4 cup chopped, 1 lime juiced","isOptional":false},{"name":"Ripe Avocado & Queso Fresco / Cheese","quantity":"1 avocado sliced, 1/2 cup crumbled cheese","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Toss diced tomatoes, red onion, jalapeño, cilantro, lime juice, and salt in a bowl to make fresh pico de gallo."},{"step":2,"text":"Warm 1 tbsp olive oil in a skillet. Add minced garlic, cumin, chili powder, and black beans with 2 tbsp water."},{"step":3,"text":"Coarsely mash half the black beans with the back of a fork and simmer for 4 minutes until warm and saucy."},{"step":4,"text":"Toast corn tortillas over an open flame or dry skillet for 30 seconds per side until warm and pliable."},{"step":5,"text":"Layer warm black beans into tortillas, top with fresh pico de gallo, avocado slices, and cheese."},{"step":6,"text":"Squeeze fresh lime wedges over top and serve immediately."}]'::jsonb,
    '10 mins',
    '10 mins',
    '20 mins',
    'Easy',
    2,
    4.7,
    ARRAY['Charring the corn tortillas on an open gas burner imparts authentic smokiness.', 'Drain and rinse black beans well to reduce excess sodium.'],
    '{"calories":310,"protein":"11g","carbs":"46g","fat":"9g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111107',
    'Dhaba Style Dal Tadka with Steamed Basmati Rice',
    'Silky yellow lentils tempered twice with fragrant garlic, cumin seeds, tomatoes, and ghee-infused Kashmiri chilies.',
    'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=800&auto=format&fit=crop&q=80',
    'North Indian',
    'Lunch',
    'VEGETARIAN',
    '[{"name":"Toor Dal & Moong Dal","quantity":"3/4 cup toor dal, 1/4 cup yellow moong dal","isOptional":false},{"name":"Basmati Rice","quantity":"1.5 cups","isOptional":false},{"name":"Ripe Tomatoes","quantity":"2 medium (finely chopped)","isOptional":false},{"name":"Garlic Cloves","quantity":"6-8 cloves (finely minced)","isOptional":false},{"name":"Desi Ghee","quantity":"3 tbsp","isOptional":false},{"name":"Cumin seeds & Whole Red Chilies","quantity":"1.5 tsp cumin, 2 dry red chilies","isOptional":false},{"name":"Kasuri Methi & Fresh Coriander","quantity":"1 tsp kasuri methi, 2 tbsp coriander","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Pressure cook washed dals with turmeric, salt, and 3.5 cups water for 4 whistles until completely tender."},{"step":2,"text":"Cook soaked basmati rice with 3 cups water until fluffy; set aside."},{"step":3,"text":"In a pan, heat 2 tbsp ghee. Sauté cumin seeds, chopped onions, and tomatoes until soft and pulpy."},{"step":4,"text":"Pour cooked dal into the tomato gravy and adjust consistency with 1/2 cup hot water. Simmer 5 minutes."},{"step":5,"text":"Prepare the second tadka: heat 1 tbsp ghee in a small ladle, fry minced garlic, dried red chilies, and Kashmiri chili powder for 30 seconds."},{"step":6,"text":"Pour the sizzling garlic tadka directly over the dal. Garnish with crushed kasuri methi and serve hot with rice."}]'::jsonb,
    '10 mins',
    '20 mins',
    '30 mins',
    'Easy',
    3,
    4.8,
    ARRAY['Using a blend of toor dal and moong dal provides both richness and silky body.', 'Do not burn garlic in the final tadka; remove from heat as soon as it turns light golden.'],
    '{"calories":380,"protein":"14g","carbs":"64g","fat":"8g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111108',
    'Chettinad Spicy Pepper Chicken Curry',
    'An explosive Tamil culinary classic featuring bone-in chicken simmered in freshly ground roasted peppercorns, fennel seeds, and curry leaves.',
    'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=800&auto=format&fit=crop&q=80',
    'South Indian',
    'Lunch',
    'NON-VEGETARIAN',
    '[{"name":"Chicken (Bone-in cuts)","quantity":"500g","isOptional":false},{"name":"Black Peppercorns","quantity":"2 tbsp (freshly crushed)","isOptional":false},{"name":"Shallots / Sambar Onions","quantity":"15 pieces (sliced)","isOptional":false},{"name":"Ripe Tomatoes","quantity":"2 medium (chopped)","isOptional":false},{"name":"Fennel Seeds & Cumin Seeds","quantity":"1 tsp each","isOptional":false},{"name":"Ginger-Garlic Paste","quantity":"1.5 tbsp","isOptional":false},{"name":"Curry Leaves & Coconut Oil","quantity":"2 sprigs curry leaves, 2.5 tbsp oil","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Dry roast black peppercorns, fennel seeds, cumin seeds, and coriander seeds until fragrant; grind into a coarse spice mix."},{"step":2,"text":"Heat coconut oil in a clay pot or heavy pan. Sputter mustard seeds and a generous handful of curry leaves."},{"step":3,"text":"Add sliced shallots and sauté until golden brown. Add ginger-garlic paste and sauté for 1 minute."},{"step":4,"text":"Add chopped tomatoes and turmeric; cook until tomatoes break down into a rich paste."},{"step":5,"text":"Add chicken pieces and half the freshly ground pepper spice powder. Sear for 5 minutes on high heat."},{"step":6,"text":"Add 1 cup water, cover, and simmer for 18-20 minutes until chicken is tender. Stir in remaining black pepper powder before serving."}]'::jsonb,
    '15 mins',
    '25 mins',
    '40 mins',
    'Medium',
    3,
    4.9,
    ARRAY['Grind whole black peppercorns fresh; pre-ground pepper lacks the signature floral heat of Chettinad cuisine.', 'Coconut oil is essential for authentic South Indian aroma.'],
    '{"calories":430,"protein":"36g","carbs":"12g","fat":"26g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111109',
    'Classic Italian Margherita Pizza',
    'Crisp artisanal crust topped with crushed San Marzano tomato sauce, creamy fresh mozzarella, fragrant sweet basil, and extra virgin olive oil.',
    'https://images.unsplash.com/photo-1604382355076-af4b0eb60143?w=800&auto=format&fit=crop&q=80',
    'Italian',
    'Lunch',
    'VEGETARIAN',
    '[{"name":"Pizza Dough (00 Flour / Yeast)","quantity":"1 ball (250g)","isOptional":false},{"name":"San Marzano Canned or Ripe Tomatoes","quantity":"1/2 cup (crushed with sea salt)","isOptional":false},{"name":"Fresh Mozzarella (Fior di Latte)","quantity":"150g (torn into chunks)","isOptional":false},{"name":"Fresh Sweet Basil Leaves","quantity":"8-10 whole leaves","isOptional":false},{"name":"Extra Virgin Olive Oil","quantity":"2 tbsp","isOptional":false},{"name":"Parmesan / Grana Padano Cheese","quantity":"1 tbsp finely grated","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Preheat oven with pizza stone or heavy baking tray at maximum heat (250°C / 485°F) for at least 30 minutes."},{"step":2,"text":"Stretch dough ball gently using your fingertips on a floured surface into a 10-12 inch round, leaving a raised outer crust."},{"step":3,"text":"Spread crushed tomato sauce thinly from the center outwards, leaving a 1-inch border."},{"step":4,"text":"Distribute torn fresh mozzarella chunks and a sprinkle of grated parmesan evenly over the sauce."},{"step":5,"text":"Slide onto the blazing hot pizza stone and bake for 8-10 minutes until cheese is bubbly and crust has charred leopard spots."},{"step":6,"text":"Scatter fresh basil leaves over top and finish with a swirl of extra virgin olive oil before slicing."}]'::jsonb,
    '20 mins',
    '10 mins',
    '30 mins',
    'Medium',
    2,
    4.9,
    ARRAY['Do not overload with tomato sauce; a thin layer ensures the crust remains crispy and not soggy.', 'Add fresh basil leaves after baking so their delicate herbal aroma stays vibrant.'],
    '{"calories":480,"protein":"19g","carbs":"62g","fat":"18g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111110',
    'Szechuan Kung Pao Chicken',
    'A fiery stir-fried Chinese wok classic featuring tender diced chicken, crunchy roasted peanuts, dried red chilies, and scallions in savory sauce.',
    'https://images.unsplash.com/photo-1525755662778-989d0524087e?w=800&auto=format&fit=crop&q=80',
    'Chinese',
    'Lunch',
    'NON-VEGETARIAN',
    '[{"name":"Chicken Breast or Thighs","quantity":"400g (cut into 1-inch cubes)","isOptional":false},{"name":"Roasted Peanuts","quantity":"1/3 cup (unsalted)","isOptional":false},{"name":"Dried Red Szechuan Chilies","quantity":"8-10 pieces (halved, seeds shaken out)","isOptional":false},{"name":"Szechuan Peppercorns","quantity":"1 tsp","isOptional":false},{"name":"Spring Onions (Scallions)","quantity":"4 stalks (cut into 1-inch batons)","isOptional":false},{"name":"Soy Sauce & Chinkiang Black Vinegar","quantity":"2 tbsp soy sauce, 1.5 tbsp vinegar","isOptional":false},{"name":"Cornstarch & Shaoxing Wine / Broth","quantity":"1 tbsp cornstarch, 2 tbsp broth","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Marinate chicken cubes with 1 tbsp soy sauce, 1 tsp cornstarch, and pinch of salt for 15 minutes."},{"step":2,"text":"Whisk sauce: 1 tbsp soy sauce, black vinegar, 1 tsp sugar, 1 tsp cornstarch, and 2 tbsp water in a small bowl."},{"step":3,"text":"Heat 2 tbsp oil in a smoking-hot wok. Add dried chilies and Szechuan peppercorns; stir-fry for 15 seconds until aromatic."},{"step":4,"text":"Add marinated chicken and stir-fry vigorously for 3-4 minutes until chicken changes color and edges are seared."},{"step":5,"text":"Toss in minced garlic, ginger, and spring onions; stir-fry for 1 minute."},{"step":6,"text":"Pour in the sauce mixture and stir constantly until glossy. Fold in roasted peanuts and serve hot with rice."}]'::jsonb,
    '15 mins',
    '10 mins',
    '25 mins',
    'Medium',
    3,
    4.8,
    ARRAY['Keep your wok intensely hot and work fast to capture authentic wok hei (breath of the wok).', 'Add roasted peanuts at the very end to preserve their crisp texture.'],
    '{"calories":420,"protein":"34g","carbs":"14g","fat":"25g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111111',
    'Authentic Punjabi Palak Paneer',
    'Tender cottage cheese cubes simmered in a velvety, emerald-green spiced spinach gravy enriched with cumin, garlic, and fresh cream.',
    'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=800&auto=format&fit=crop&q=80',
    'North Indian',
    'Dinner',
    'VEGETARIAN',
    '[{"name":"Fresh Spinach (Palak)","quantity":"400g (washed and trimmed)","isOptional":false},{"name":"Paneer (Cottage Cheese)","quantity":"250g (cubed)","isOptional":false},{"name":"Onions & Ripe Tomatoes","quantity":"1 large onion chopped, 2 tomatoes pureed","isOptional":false},{"name":"Garlic & Ginger","quantity":"1.5 tbsp minced garlic, 1 tbsp ginger","isOptional":false},{"name":"Desi Ghee or Butter","quantity":"2 tbsp","isOptional":false},{"name":"Garam Masala & Cumin","quantity":"1/2 tsp garam masala, 1 tsp cumin","isOptional":false},{"name":"Fresh Cream","quantity":"2 tbsp","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Blanch spinach leaves in boiling salted water for 2 minutes, then immediately plunge into an ice-water bath."},{"step":2,"text":"Drain spinach and blend with 1 green chili into a vibrant smooth green puree without adding excess water."},{"step":3,"text":"Heat ghee in a pan. Sputter cumin seeds and sauté minced garlic and onions until soft and light golden."},{"step":4,"text":"Add pureed tomatoes, turmeric, coriander powder, and salt. Cook 5 minutes until oil separates."},{"step":5,"text":"Pour in the vibrant spinach puree and simmer gently covered for 4-5 minutes."},{"step":6,"text":"Add paneer cubes, garam masala, and fresh cream. Cook for 2 minutes and serve warm with garlic naan."}]'::jsonb,
    '15 mins',
    '15 mins',
    '30 mins',
    'Easy',
    3,
    4.9,
    ARRAY['The ice-water bath immediately shocks the spinach and preserves the vibrant green restaurant color.', 'Do not overcook the spinach puree once added to keep nutrients and color fresh.'],
    '{"calories":340,"protein":"18g","carbs":"14g","fat":"24g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111112',
    'Italian Spaghetti Bolognese',
    'Slow-simmered rich Italian meat sauce made with minced chicken, Italian plum tomatoes, aromatic mirepoix, and herbs tossed with al dente spaghetti.',
    'https://images.unsplash.com/photo-1551183053-bf91a1d81141?w=800&auto=format&fit=crop&q=80',
    'Italian',
    'Dinner',
    'NON-VEGETARIAN',
    '[{"name":"Spaghetti Pasta","quantity":"350g","isOptional":false},{"name":"Minced Chicken / Poultry Meat","quantity":"400g","isOptional":false},{"name":"Italian Whole Plum Tomatoes","quantity":"1 can (400g crushed)","isOptional":false},{"name":"Onion, Carrot & Celery (Mirepoix)","quantity":"1 onion, 1 carrot, 1 celery stick (finely minced)","isOptional":false},{"name":"Garlic & Olive Oil","quantity":"4 cloves minced, 2 tbsp olive oil","isOptional":false},{"name":"Dried Oregano & Fresh Basil","quantity":"1 tsp oregano, 5 leaves fresh basil","isOptional":false},{"name":"Grated Parmesan Cheese","quantity":"1/3 cup","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Heat olive oil in a heavy pot. Sauté finely minced onion, carrot, and celery over medium heat for 6-8 minutes until sweet and tender."},{"step":2,"text":"Add minced garlic and ground poultry meat. Cook breaking up clumps with a spoon until lightly browned (5-6 minutes)."},{"step":3,"text":"Pour in crushed plum tomatoes, tomato paste, dried oregano, salt, and black pepper. Stir well."},{"step":4,"text":"Cover and simmer sauce on low heat for 25-30 minutes, stirring occasionally until thick and rich."},{"step":5,"text":"Boil spaghetti in generously salted water until al dente (about 8-9 minutes); reserve 1/2 cup starchy pasta water."},{"step":6,"text":"Toss drained pasta directly into the Bolognese sauce with a splash of pasta water. Serve topped with parmesan and fresh basil."}]'::jsonb,
    '15 mins',
    '35 mins',
    '50 mins',
    'Medium',
    4,
    4.8,
    ARRAY['Finely mincing the vegetables (soffritto) allows them to melt into the meat sauce seamlessly.', 'Always finish the pasta in the sauce for 1 minute so the noodles absorb the savory juices.'],
    '{"calories":520,"protein":"32g","carbs":"65g","fat":"14g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111113',
    'Sizzling Mexican Chicken Fajitas',
    'Juicy spiced chicken breast strips seared with sweet bell peppers and red onions, served with warm tortillas, guacamole, and lime.',
    'https://images.unsplash.com/photo-1534766555764-ce878a5e3a2b?w=800&auto=format&fit=crop&q=80',
    'Mexican',
    'Dinner',
    'NON-VEGETARIAN',
    '[{"name":"Chicken Breasts","quantity":"500g (cut into 1/2-inch strips)","isOptional":false},{"name":"Tri-color Bell Peppers (Capsicum)","quantity":"2 medium (sliced into strips)","isOptional":false},{"name":"Red Onion","quantity":"1 large (sliced into strips)","isOptional":false},{"name":"Fajita Seasoning (Cumin, Smoked Paprika, Garlic Powder)","quantity":"1.5 tbsp","isOptional":false},{"name":"Lime Juice & Olive Oil","quantity":"Juice of 1 lime, 2.5 tbsp oil","isOptional":false},{"name":"Warm Flour Tortillas","quantity":"6 tortillas","isOptional":true}]'::jsonb,
    '[{"step":1,"text":"Toss sliced chicken with fajita seasoning, lime juice, 1 tbsp olive oil, and salt. Marinate for 15 minutes."},{"step":2,"text":"Heat a cast-iron skillet over high heat with 1 tbsp oil until lightly smoking."},{"step":3,"text":"Add chicken strips in a single layer and sear for 3 minutes per side until nicely charred and cooked through; transfer to a plate."},{"step":4,"text":"Add remaining oil, bell peppers, and red onions to the hot skillet. Sauté vigorously for 4-5 minutes until tender-crisp with charred edges."},{"step":5,"text":"Return chicken and resting juices back to the sizzling skillet; toss together for 1 minute."},{"step":6,"text":"Serve sizzling straight from the pan with warm flour tortillas, fresh salsa, and cooling sour cream."}]'::jsonb,
    '15 mins',
    '15 mins',
    '30 mins',
    'Easy',
    3,
    4.8,
    ARRAY['A ripping hot cast iron skillet gives the classic restaurant sizzle and charred smoky flavor.', 'Keep peppers tender-crisp; overcooking makes them limp.'],
    '{"calories":440,"protein":"38g","carbs":"28g","fat":"20g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111114',
    'Malabar Coconut Fish Curry',
    'Fresh kingfish steaks simmered in a velvety coconut milk gravy flavored with kudampuli (pot tamarind), mustard seeds, and fresh curry leaves.',
    'https://images.unsplash.com/photo-1620894580123-466ad3a0ca06?w=800&auto=format&fit=crop&q=80',
    'South Indian',
    'Dinner',
    'NON-VEGETARIAN',
    '[{"name":"Fish Steaks (Kingfish / Seer Fish)","quantity":"500g","isOptional":false},{"name":"Thick Coconut Milk & Thin Coconut Milk","quantity":"1 cup thick, 1 cup thin","isOptional":false},{"name":"Kudampuli (Malabar Tamarind)","quantity":"3 pieces (soaked in warm water)","isOptional":false},{"name":"Shallots & Green Chilies","quantity":"10 shallots sliced, 3 chilies slit","isOptional":false},{"name":"Ginger & Garlic Paste","quantity":"1 tbsp","isOptional":false},{"name":"Kashmiri Chili Powder & Turmeric","quantity":"1.5 tbsp chili, 1/2 tsp turmeric","isOptional":false},{"name":"Curry Leaves & Coconut Oil","quantity":"2 sprigs curry leaves, 2 tbsp oil","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Soak kudampuli pieces in 1/2 cup warm water for 15 minutes."},{"step":2,"text":"In an earthen manchatti (clay pot), heat coconut oil. Sputter mustard seeds, fenugreek seeds, and fresh curry leaves."},{"step":3,"text":"Add sliced shallots, ginger-garlic paste, and green chilies. Sauté until shallots turn soft."},{"step":4,"text":"Add Kashmiri chili powder, coriander powder, turmeric, thin coconut milk, soaked kudampuli water, and salt. Bring to a boil."},{"step":5,"text":"Gently slide in fish steaks. Cover and simmer gently on medium-low heat for 8-10 minutes."},{"step":6,"text":"Lower heat to lowest, pour in thick coconut milk, swirl pot gently without stirring with spoon, and turn off heat."}]'::jsonb,
    '15 mins',
    '20 mins',
    '35 mins',
    'Medium',
    3,
    4.9,
    ARRAY['Swirl the clay pot rather than stirring with a ladle to prevent delicate fish pieces from breaking.', 'Fish curry tastes even richer the next day as the coconut and tamarind penetrate the fish.'],
    '{"calories":390,"protein":"32g","carbs":"8g","fat":"26g"}'::jsonb
),
(
    '11111111-1111-1111-1111-111111111115',
    'Crispy Punjabi Potato & Pea Samosa',
    'Golden, triangular flaky pastries stuffed with a robustly spiced filling of cumin potatoes, green peas, pomegranate seeds, and ginger.',
    'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&auto=format&fit=crop&q=80',
    'North Indian',
    'Snacks',
    'VEGETARIAN',
