    '[{"name":"Khoya / Mawa (Evaporated Milk Solids)","quantity":"200g (grated)","isOptional":false},{"name":"Paneer (Chenna)","quantity":"75g (freshly grated and smooth)","isOptional":false},{"name":"All-Purpose Flour (Maida)","quantity":"3 tbsp","isOptional":false},{"name":"Baking Soda","quantity":"1/4 tsp","isOptional":false},{"name":"Sugar","quantity":"1.5 cups","isOptional":false},{"name":"Green Cardamom Pods & Rose Water","quantity":"4 crushed pods, 1 tsp rose water","isOptional":false},{"name":"Saffron Strands & Ghee for Frying","quantity":"pinch saffron, ghee for frying","isOptional":true}]'::jsonb,
