(
    '11111111-1111-1111-1111-111111111128',
    'Goan Coconut Prawn Balchão Curry',
    'Plump succulent tiger prawns cooked in a spicy, tangy Goan coconut curry with tamarind pulp, dried red chilies, and coconut vinegar.',
    'https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?w=800&auto=format&fit=crop&q=80',
    'Indian',
    'Curry',
    'NON-VEGETARIAN',
    '[{"name":"Tiger Prawns / Shrimp","quantity":"400g (shelled and deveined)","isOptional":false},{"name":"Fresh Grated Coconut","quantity":"1 cup","isOptional":false},{"name":"Kashmiri Dried Red Chilies","quantity":"5 pieces (soaked in warm water)","isOptional":false},{"name":"Tamarind Pulp","quantity":"1.5 tbsp","isOptional":false},{"name":"Onion & Garlic","quantity":"1 onion finely chopped, 6 cloves garlic","isOptional":false},{"name":"Coconut Oil & Curry Leaves","quantity":"2 tbsp coconut oil, 1 sprig curry leaves","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Blend grated coconut, soaked red chilies, garlic, coriander seeds, cumin, and tamarind with 1/2 cup water into a fine spice paste."},{"step":2,"text":"Heat coconut oil in a pan. Sauté chopped onions and green chilies until translucent."},{"step":3,"text":"Pour in the ground Goan coconut masala paste and cook on medium heat for 4-5 minutes until oil glazes the sides."},{"step":4,"text":"Add 1 cup water and salt; bring curry to a gentle simmer."},{"step":5,"text":"Add cleaned prawns to the bubbling curry. Cook for just 3-4 minutes until prawns curl into a ''C'' shape and turn opaque pink."},{"step":6,"text":"Turn off heat immediately to prevent prawns from overcooking. Serve hot with steamed Goan red rice or basmati."}]'::jsonb,
    '15 mins',
    '15 mins',
    '30 mins',
    'Medium',
