    'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop&q=80',
    'Italian',
    'Soup',
    'VEGETARIAN',
    '[{"name":"Ripe Vine Tomatoes","quantity":"1 kg (halved)","isOptional":false},{"name":"Garlic Head","quantity":"1 whole head (top sliced off)","isOptional":false},{"name":"Yellow Onion","quantity":"1 large (quartered)","isOptional":false},{"name":"Fresh Basil Leaves","quantity":"1 cup firmly packed","isOptional":false},{"name":"Vegetable Broth","quantity":"2 cups","isOptional":false},{"name":"Extra Virgin Olive Oil & Cream","quantity":"3 tbsp olive oil, 2 tbsp cream","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Preheat oven to 200°C (400°F). Arrange halved tomatoes, quartered onion, and garlic head on a baking tray."},{"step":2,"text":"Drizzle generously with olive oil, sea salt, and black pepper. Roast for 30 minutes until tomatoes are slightly charred and caramelized."},{"step":3,"text":"Squeeze roasted garlic cloves out of skins into a blender with the roasted tomatoes, onions, and pan juices."},{"step":4,"text":"Add fresh basil leaves and vegetable broth; blend on high speed until completely smooth and velvety."},{"step":5,"text":"Pour soup into a pot, warm through for 3 minutes, and adjust seasoning."},{"step":6,"text":"Ladle into warm bowls, swirl with cream, garnish with basil, and serve with crusty garlic bread."}]'::jsonb,
