    'Chinese',
    'Soup',
    'NON-VEGETARIAN',
    '[{"name":"Chicken Breast","quantity":"200g (boiled and finely shredded)","isOptional":false},{"name":"Chicken Broth / Stock","quantity":"4 cups","isOptional":false},{"name":"Mushrooms (Wood Ear or Shiitake)","quantity":"1/2 cup (sliced)","isOptional":false},{"name":"Bamboo Shoots","quantity":"1/3 cup (julienned)","isOptional":false},{"name":"Chinkiang Black Vinegar or Rice Vinegar","quantity":"3 tbsp","isOptional":false},{"name":"Coarsely Ground White Pepper & Soy Sauce","quantity":"1.5 tsp white pepper, 2 tbsp soy sauce","isOptional":false},{"name":"Cornstarch & Sesame Oil","quantity":"2.5 tbsp cornstarch slurry, 1 tsp sesame oil","isOptional":false}]'::jsonb,
    '[{"step":1,"text":"Bring chicken broth to a gentle simmer in a soup pot."},{"step":2,"text":"Add shredded chicken, sliced mushrooms, and bamboo shoots; simmer for 5 minutes."},{"step":3,"text":"Stir in soy sauce, chili paste, white pepper, and salt."},{"step":4,"text":"Stir cornstarch with 3 tbsp cold water; pour into simmering soup while stirring until broth turns clear and glossy."},{"step":5,"text":"Turn off heat and immediately stir in black vinegar and toasted sesame oil."},{"step":6,"text":"Ladle into soup bowls, top with sliced green spring onions, and serve steaming hot."}]'::jsonb,
